from pathlib import Path
import json,copy,hashlib,sys
P=Path(__file__).resolve().parent; R=P.parents[3]
rows={r['plannedId']:r for r in json.loads((P/'approved-blueprints.json').read_text())};cases=[]
def build(n,title,context,question,insight,mental,specs,qualities,explanations):
 r=rows[f'TC-{n}'];c={k:r[k] for k in ['partId','topicId','domain','requiredLevel','primaryPattern','secondaryPatterns','scenarioFamilyId','trainingEligible','assessmentEligible','sourceTopicExplanation']}
 c.update(id=r['plannedId'],revision=1,type='single-best',title=title,context=context,question=question,keyInsight=insight,mentalModel=mental,decisiveFacts=r['decisiveFactsConcept'],decisiveMutation=r['decisiveMutationConcept'],authorRationale=r['whyLevel'],options=[])
 for i,(spec,q,exp) in enumerate(zip(specs,qualities,explanations)):
  text,pattern,tempt,when=spec
  c['options'].append(dict(id='ABCD'[i],text=text,decisionQuality=q,isBest=q==1,reasoningPattern=pattern,failurePattern=None if q==1 else 'constraint-mismatch',explanation=exp,whyTempting=tempt,whyNotBest='При данных условиях это лучшее решение. '+exp if q==1 else exp,whenItWouldBeBest=when))
 cases.append(c)
riskctx='Вы обновляете запись риска отказа внешнего канала. Отказ ещё не произошёл; владелец риска и резервный план уже утверждены. Поздний наблюдаемый сигнал оставляет 3 рабочих дня до возможного отказа, ранний проверенный индикатор — 7. Ранний индикатор признан достаточным основанием для подготовки резерва. Подготовка резервного канала занимает {duration}; ускорить её дополнительными людьми нельзя. Резерв доступен при обоих сигналах. Его ранняя подготовка дольше связывает ресурс, поэтому согласованное правило — начинать по позднему сигналу, если времени хватает, иначе по раннему. Стоимость и допустимость этих действий согласованы.'
riskspec=[
('Оставить запуск подготовки по позднему сигналу; указать его и владельца действия в записи риска.','late-sufficient-response','Поздний сигнал сокращает срок связывания резерва.','Если подготовка занимает не больше трёх рабочих дней и согласованное правило допускает подготовку по позднему сигналу.'),
('Начинать подготовку по раннему индикатору; закрепить этот момент запуска и действие владельца в реестре.','early-feasible-response','Раннее начало оставляет больше времени до возможного отказа.','Если подготовка не помещается в три дня, но помещается в семь, а ранний индикатор и резервирование согласованы.'),
('Начинать подготовку после фактического отказа; до него следить за сигналами без связывания резерва.','reactive-reserve','Ресурс не расходуется на событие, которое может не наступить.','Если допустимый перерыв после отказа покрывает всю подготовку и владелец риска заранее утвердил такой режим реагирования.'),
('Подготовить резерв сейчас, до появления обоих сигналов; поддерживать его готовность до закрытия риска.','always-ready-reserve','Готовый резерв исключает зависимость от своевременного обнаружения сигнала.','Если сигналы ненадёжны или опоздают, последствия не допускают перерыва и владелец отдельно одобрил постоянное резервирование.')]
for n,d,qs,ex in [
(104,1,[1,.7,.2,.4],['Три дня после позднего сигнала покрывают один день подготовки. Ранний запуск не добавляет необходимой защиты, но дольше связывает ресурс.','Семь дней достаточны, но достаточно и трёх. Поэтому раннее связывание резерва противоречит согласованному правилу выбора сигнала.','После отказа потребуется ещё день подготовки. План должен быть готов до события; разрешения на такой перерыв нет.','Подготовка до любого сигнала обеспечивает готовность, но связывает ресурс ещё раньше без основания менять согласованное правило.']),
(105,5,[.3,1,.1,.6],['Трёх дней недостаточно для пятидневной подготовки. Наличие владельца и записи не делает этот момент запуска исполнимым.','Семь дней покрывают пять дней подготовки. Поздний сигнал оставил бы дефицит двух дней, поэтому нужен утверждённый ранний индикатор.','Реакция после отказа оставляет весь пятидневный период без подготовленного резерва и не выполняет план защиты до события.','Резерв окажется готов, но можно начать по согласованному раннему индикатору и не связывать ресурс до его появления.'])]:
 build(n,'Момент подготовки резервного канала',riskctx.format(duration="1 рабочий день" if d==1 else "5 рабочих дней"),'Какой момент начала подготовки закрепить в реестре?','Сигнал полезен только тогда, когда после него остаётся время выполнить предусмотренное действие.','Сопоставьте время предупреждения с длительностью реакции, затем выберите достаточный сигнал с учётом согласованной цены раннего действия.',riskspec,qs,ex)
flowbase='Вы отвечаете за поток работ перед ревью. Сейчас в очереди 8 сопоставимых задач, обычная мощность — 10 задач в неделю. {arrival} Очередь на конец каждой недели не должна превышать 14 задач и должна быть снята к концу четвёртой недели. WIP-лимит и приоритеты не меняются, качество мер одинаково. Взаимоисключающие способы усиления: помощь ревьюера добавляет 4 задачи в неделю на первые две недели, её цена — 20 единиц упущенной работы; продление ещё на две недели стоит дополнительно 80. Автоматизация типовой проверки стоит 40 единиц, на первой неделе снижает мощность до 8, затем даёт 16 задач в неделю. Эффект проверен, возврат после настройки бесплатен. Сократить подтверждённый вход нельзя; других мер в этом цикле нет. Сравниваете полные планы на четыре недели по выполнимости и цене; после горизонта нельзя оставлять устойчивый дефицит мощности.'
flowspec=[
('Оставить обычную мощность на четыре недели; следить за очередью, не отвлекая ресурсы на помощь или настройку.','unchanged-capacity','Не нужно оплачивать изменения, если очередь способна рассосаться сама.','Если подтверждённый вход ниже мощности настолько, что исходная очередь исчезнет к обязательному сроку и предел очереди не будет нарушен.'),
('Взять помощь ревьюера на первые две недели без продления; затем вернуться к обычной мощности.','temporary-capacity','Краткая помощь быстро снижает очередь и меньше отвлекает ресурс от другой работы.','Если после временного пика обычная мощность покрывает вход и двух недель помощи достаточно для снятия очереди к сроку.'),
('Взять помощь ревьюера на четыре недели, оплатив продление; сохранить текущую процедуру проверки.','extended-capacity','Дополнительная мощность действует сразу и не требует переходной недели настройки.','Если четыре недели помощи снимают очередь, затем обычная мощность покрывает вход, а автоматизация недоступна или дороже полного периода помощи.'),
('Выделить первую неделю на автоматизацию типовой проверки; со второй использовать повышенную мощность без привлечения ревьюера.','structural-capacity','Устойчивое повышение мощности устраняет повторяющийся дефицит.','Если вход остаётся выше обычной мощности, переходная очередь допустима, а автоматизация выполняет срок дешевле временного усиления.')]
for n,arr,qs,ex in [
(106,'В первую неделю поступит 12 задач; затем подтверждённый вход возвращается к 8 задачам в неделю.',[.2,1,.5,.75],[
'Остаток по неделям: 10, 8, 6, 4. Лимит не нарушен, но очередь не снята к концу четвёртой недели.',
'Остаток: 6, 0, 0, 0. План за 20 единиц выполняет оба ограничения, а обычная мощность 10 после пика покрывает вход 8.',
'Очередь также исчезнет на второй неделе. Продление не нужно: после пика обычной мощности хватает, а цена вырастает с 20 до 100.',
'Остаток: 12, 4, 0, 0. План выполним, но стоит 40 вместо 20; длительного дефицита после пика нет.']),
(107,'Подтверждённый вход остаётся 12 задач в неделю весь четырёхнедельный период и далее.',[.1,.3,.65,1],[
'Остаток: 10, 12, 14, 16. План нарушает предел очереди на четвёртой неделе и не устраняет дефицит мощности.',
'Остаток: 6, 4, 6, 8. После окончания помощи очередь снова растёт; к обязательному сроку она не снята.',
'Остаток: 6, 4, 2, 0. На четырёх неделях план выполним, но стоит 100, а после завершения помощи вход снова превышает мощность.',
'Остаток: 12, 8, 4, 0. Переходный рост укладывается в предел 14, очередь снята к сроку. Цена 40 меньше 100, а мощность 16 покрывает дальнейший вход 12.'])]:
 build(n,'План разгрузки ревью',flowbase.format(arrival=arr),'Какой план выбрать?', 'Одинаковая очередь сегодня не означает одинаковую причину и одинаковую длительность усиления.','Проверьте очередь на каждом шаге: остаток плюс вход минус мощность. Среди планов, выполняющих ограничения, сравните цену и устойчивость после временной помощи.',flowspec,qs,ex)
logbase='Вы вместе с SRE выбираете режим хранения диагностических записей одного класса за неделю. {volume} Одна запись занимает 1 КБ; используйте десятичные единицы. Записи структурированы, без персональных данных и связаны trace ID, другого источника подробностей нет. Для расследования нужны не менее 100 полных репрезентативных примеров за неделю; достаточность этого количества проверена. Лимит на класс — 1 ГБ, увеличить его сейчас нельзя; остальные потоки уже оптимизированы. Инструмент поддерживает два режима: все записи или равномерно каждый сотый экземпляр. Другие настройки недоступны до следующего периода. Полный точный счётчик в метриках сохраняется при любом режиме; распределение подтипов одинаковое, систематического смещения выборки нет.'
logspec=[
('Сохранить все записи класса на неделю и использовать полный счётчик метрик для оценки частоты.','full-event-retention','Все подробности остаются доступными для расследования.','Если полный недельный поток помещается в лимит и сохраняет диагностический минимум, а доступное сэмплирование теряет слишком много примеров.'),
('Сохранить равномерно каждый сотый экземпляр на неделю, сохранив полный счётчик событий в метриках.','sufficient-event-sampling','Можно сократить хранение, не потеряв точную частоту событий.','Если полный поток превышает лимит, а каждый сотый экземпляр даёт достаточно репрезентативных полных примеров.'),
('Для этого периода запросить повышение лимита и запланировать хранение всех записей после его согласования.','budget-exception','Дополнительный бюджет позволяет сохранить подробности без выбора выборки.','Если изменение лимита доступно до начала периода и согласовано, а расследованию нужны все записи, которые не помещаются в прежний лимит.'),
('Отложить выбор до следующего периода, когда появятся другие настройки; текущий период оставить без утверждённого плана хранения подробностей.','deferred-observability-plan','Более гибкий инструмент может позволить точнее подобрать хранение.','Если сбор подробностей в текущем периоде ещё не требуется, запуск можно перенести и доступные сейчас режимы не выполняют будущие требования.')]
for n,vol,qs,ex in [
(108,'За неделю возникает 10 000 000 событий этого класса.',[.3,1,.2,.1],[
'Полный поток занимает 10 ГБ при лимите 1 ГБ. Достаточное число примеров не компенсирует невыполнимое требование к хранению.',
'Сохраняется 100 000 записей, или 100 МБ. Это укладывается в 1 ГБ и превышает минимум 100 примеров; точная частота остаётся в метриках.',
'Изменение лимита сейчас недоступно. Есть исполнимый режим, который сохраняет нужные свидетельства без такого согласования.',
'Диагностические данные нужны за текущую неделю. Отложенный выбор не обеспечивает их сохранение, хотя доступный режим удовлетворяет требованиям.']),
(109,'За неделю возникает 500 событий этого класса.',[1,.3,.2,.1],[
'Все 500 записей занимают 0,5 МБ и помещаются в 1 ГБ. Это сохраняет требуемые подробности; сэмплирование здесь оставило бы только пять примеров.',
'Каждый сотый даст пять записей вместо требуемых 100. Полный счётчик показывает частоту, но не восстанавливает утраченные подробности.',
'Полный поток уже помещается в лимит. Запрос недоступного повышения не решает задачу лучше существующего режима.',
'Недельное расследование требует подробностей сейчас. Их можно сохранить полностью в текущем лимите; ожидание новых настроек оставляет задачу нерешённой.'])]:
 build(n,'Хранение диагностических событий',logbase.format(volume=vol),'Какой план хранения выбрать на текущую неделю?', 'Точный счётчик событий и подробные примеры отвечают на разные вопросы. Доля сохраняемых записей полезна только вместе с абсолютным числом примеров.','Одновременно проверьте бюджет хранения и достаточность диагностических свидетельств. Сэмплирование частого события и редкого события даёт разную полноту расследования.',logspec,qs,ex)
(P/'cases.json').write_text(json.dumps({'schemaVersion':'2.0','source':'Six-case full candidate from accepted completion02 blueprints; not production','cases':cases},ensure_ascii=False,indent=2)+'\n')
(P/'blind-cases.json').write_text(json.dumps([{'id':c['id'],'context':c['context'],'question':c['question'],'options':[{k:o[k] for k in ['id','text']} for o in c['options']]} for c in cases],ensure_ascii=False,indent=2)+'\n')
print('Authored',len(cases),'cases')
